SETS = {"gold": GOLD, "verify": VERIFY}


def pipeline_text(case: Case) -> str:
    return case.text.replace(" || ", " ")


def _params(kind: str) -> list:
    return [pytest.param(eid, case, id=f"{eid}-{name}-{kind}-{i:02d}")
            for name, cases_by_entity in SETS.items()
            for eid, cases in cases_by_entity.items()
            for i, case in enumerate(cases[kind])]


@pytest.fixture(scope="module")
def all_entities():
    return load_entities(ROOT / "config" / "entities.yaml")


def matched_ids(case: Case, entities) -> list[str]:
    return [m.entity_id for m in match_text(pipeline_text(case), entities)]


def test_cases_have_sources_and_do_not_overlap():
    for name, cases_by_entity in SETS.items():
        for eid, cases in cases_by_entity.items():
            for kind in ("pos", "neg"):
                texts = [case.text for case in cases[kind]]
                assert len(set(texts)) == len(texts), (name, eid, kind)
                for case in cases[kind]:
                    url = urlsplit(case.url)
                    assert url.scheme == "https" and url.netloc, case
                    assert not url.netloc.endswith("stellar.org"), case
    for eid in GOLD:
        pos = {case.text for name in SETS for case in SETS[name].get(eid, {}).get("pos", [])}
        neg = {case.text for name in SETS for case in SETS[name].get(eid, {}).get("neg", [])}
        assert not pos & neg, eid


@pytest.mark.parametrize("entity_id, case", _params("pos"))
def test_real_positive_matches_its_entity(entity_id, case, all_entities):
    assert entity_id in matched_ids(case, all_entities), case.url


@pytest.mark.parametrize("entity_id, case", _params("neg"))
def test_real_negative_does_not_match_the_entity(entity_id, case, all_entities):
    assert entity_id not in matched_ids(case, all_entities), case.url
